# -*- coding: utf-8 -*-
"""第五批：维护/修复、卡盘转接、材质匹配、场景与误用型答案页（36 篇）"""
NEW = [
 {'slug': 'how-to-clean-resin-off-router-bits', 'q': 'How do I get burnt resin off a router bit?', 'a': 'Soak the bit in oven cleaner or a dedicated bit cleaner for 10-15 minutes, then scrub with a brass brush. Never use a file or sandpaper on the carbide.', 'body': '<table><tr><th>Deposit</th><th>What removes it</th><th>What damages the bit</th></tr><tr><td>Pine resin</td><td>Oven cleaner, 10 min, brass brush</td><td>Scraping with a blade</td></tr><tr><td>Burnt MDF glue</td><td>Overnight soak in bit cleaner</td><td>Wire wheel on the flutes</td></tr><tr><td>Pitch on a saw blade (same rule)</td><td>Blade cleaner, stiff nylon brush</td><td>Caustic soak on brazed teeth</td></tr><tr><td>Rust film on the shank only</td><td>Fine Scotch-Brite, then oil</td><td>Leaving it, then clamping it in the collet</td></tr></table><p><b>Why it matters:</b> resin on the cutting edge raises the temperature of the edge, and heat is what dulls carbide. A bit that looks clean but feels sticky will burn the next workpiece.</p><p><b>Do this after every session:</b> wipe the flutes, check the bearing spins free, and oil the shank lightly. Remove the bit from the collet — resin left in the collet is what makes the next bit slip.</p>', 'answer_short': 'Soak in oven cleaner or bit cleaner for 10-15 minutes and scrub with a brass brush. Never touch the carbide with a file or sandpaper.', 'links': ['RB-12W', 'RB-15HW']},
 {'slug': 'drill-bit-sharpening-at-home', 'q': 'Can you sharpen drill bits at home?', 'a': 'Yes on a bench grinder with a gauge, for bits 3 mm and up. A hand-sharpened bit is fine for wood and mild steel but will not hold in stainless.', 'body': '<table><tr><th>Method</th><th>Bits it suits</th><th>Realistic result</th></tr><tr><td>Bench grinder + angle gauge</td><td>3 mm and up, HSS</td><td>Good for wood and mild steel</td></tr><tr><td>Drill doctor style sharpener</td><td>2-13 mm</td><td>Repeatable 118 or 135 degrees</td></tr><tr><td>Hand stone</td><td>Touch-up only</td><td>Rounds the point if you are not careful</td></tr><tr><td>Carbide bits</td><td>Diamond wheel only</td><td>Usually not worth it below 10 mm</td></tr></table><p><b>The two angles that matter:</b> point angle (118 degrees for general work, 135 degrees for hard material) and relief behind the edge. If the relief is wrong the bit rubs instead of cutting and the hole work-hardens.</p><p><b>When to stop sharpening:</b> once a bit is shorter than about 60% of its original flute length the web is too thick, and no amount of grinding brings it back.</p>', 'answer_short': 'Yes, on a bench grinder with an angle gauge for bits 3 mm and up. Hand-sharpened bits work in wood and mild steel but fail in stainless.', 'links': ['DB-51C', 'DB-21M']},
 {'slug': 'why-drill-bit-slips-in-chuck', 'q': 'Why does my drill bit keep slipping in the chuck?', 'a': 'Almost always one of three things: the shank is not seated past the jaws, the shank is scored, or the chuck jaws are worn. Check them in that order.', 'body': '<table><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr><tr><td>Slips on the first heavy cut</td><td>Shank sitting on the jaw tips</td><td>Seat it fully, then tighten all three positions on a keyed chuck</td></tr><tr><td>Spins immediately, every time</td><td>Scored or out-of-round shank</td><td>Replace the bit; a chewed shank cannot be repaired</td></tr><tr><td>Only large bits slip</td><td>Worn jaws or a keyless chuck at its limit</td><td>Use a keyed chuck, or a 1/2 in chuck for 13 mm shanks</td></tr><tr><td>Slips and wobbles</td><td>Hex shank in a three-jaw chuck</td><td>Use round shanks in a chuck</td></tr></table><p><b>The cheap habits:</b> wipe the shank before clamping, never clamp on the flutes, and tighten a keyed chuck in all three holes. Snugging one hole is the single most common cause of a slipping bit.</p>', 'answer_short': 'The shank is not seated past the jaws, the shank is scored, or the jaws are worn. Seat it fully, tighten a keyed chuck in all three holes, and replace scored bits.', 'links': ['DB-13M', 'DB-51C']},
 {'slug': 'keyless-vs-keyed-drill-chuck', 'q': 'Keyless or keyed chuck — which holds better?', 'a': 'A keyed chuck holds tighter and does not loosen under load, which is why drill presses still use one. Keyless is faster for small bits and hand drilling.', 'body': '<table><tr><th></th><th>Keyed chuck</th><th>Keyless chuck</th></tr><tr><td>Grip force</td><td>Higher</td><td>Lower, hand-tightened</td></tr><tr><td>Loosens under load</td><td>Rarely</td><td>Yes, especially with left-hand rotation</td></tr><tr><td>Speed of change</td><td>Slow, key required</td><td>Fast</td></tr><tr><td>Best for</td><td>Hole saws, augers, large bits, drill press</td><td>Bits under 10 mm, driving screws</td></tr><tr><td>Failure mode</td><td>Jaws wear, key lost</td><td>Internal thread strips</td></tr></table><p><b>Practical split:</b> keep a keyless chuck on the cordless drill for bits up to 10 mm, and a keyed chuck on the drill press for everything above that. Anything with a hole saw belongs on the keyed chuck.</p>', 'answer_short': 'A keyed chuck grips harder and stays tight under load. Keyless is faster for small bits but loosens with hole saws and large diameters.', 'links': ['DB-21M', 'HS-8']},
 {'slug': 'how-to-check-router-runout', 'q': 'How do I check whether my router or collet is out of true?', 'a': 'Mount a known-good bit, spin the spindle by hand, and read a dial indicator on the shank just below the collet: under 0.05 mm (0.002 in) is healthy, over 0.1 mm explains chatter and burnt edges.', 'body': '<table><tr><th>Reading at the shank</th><th>Verdict</th><th>Next step</th></tr><tr><td>Under 0.03 mm</td><td>Good</td><td>Look elsewhere for chatter</td></tr><tr><td>0.03-0.05 mm</td><td>Acceptable</td><td>Clean the collet and re-seat</td></tr><tr><td>0.05-0.1 mm</td><td>Poor</td><td>New collet, check for resin or a burr</td></tr><tr><td>Over 0.1 mm</td><td>Bad</td><td>Bent shank or damaged spindle taper — stop using it</td></tr></table><p><b>How to isolate the cause:</b> measure on the bare collet nut, then on a bit shank. If the nut is true and the bit is not, the bit is bent. If both are out, the spindle or the collet is worn.</p><p><b>What runout does to your work:</b> one flute does all the cutting, the edge overheats, and you get a fuzzy edge plus a burning smell long before the bit looks dull.</p>', 'answer_short': 'Read a dial indicator on the bit shank below the collet: under 0.05 mm is healthy, over 0.1 mm means a bent shank or a worn collet.', 'links': ['RB-12W', 'RB-12HW']},
 {'slug': 'hex-shank-vs-round-shank-bits', 'q': 'Hex shank or round shank drill bits?', 'a': 'Hex shanks for impact drivers and quick-change holders, round shanks for three-jaw chucks and drill presses. A round shank in an impact driver spins in the jaws.', 'body': '<table><tr><th></th><th>1/4 in hex shank</th><th>Round shank</th></tr><tr><td>Fits</td><td>Impact drivers, quick-change holders</td><td>Three-jaw chucks, drill presses</td></tr><tr><td>Torque transfer</td><td>Good, no slip</td><td>Depends on jaw grip</td></tr><tr><td>Runout</td><td>Slightly worse, holder adds error</td><td>Better, best in a press</td></tr><tr><td>Max size</td><td>Usually 10 mm, above that it is rare</td><td>Any size the chuck takes</td></tr><tr><td>Best for</td><td>Driving, small holes, tight spaces</td><td>Accurate holes, large diameters</td></tr></table><p><b>The rule:</b> if the hole has to be located precisely, use a round shank in a chuck or a press. If you are swapping between driving and drilling all day, hex wins on speed.</p>', 'answer_short': 'Hex for impact drivers and quick-change holders, round for chucks and drill presses. Round shanks spin in an impact driver and hex shanks add runout in a press.', 'links': ['DB-13M', 'DB-51C']},
 {'slug': 'sds-plus-vs-sds-max-bits', 'q': 'SDS Plus or SDS Max — which fits my rotary hammer?', 'a': 'SDS Plus for hammers up to about 1 in drilling capacity, SDS Max for 1-1/2 in and above. The shanks are different sizes and are not interchangeable.', 'body': '<table><tr><th></th><th>SDS Plus</th><th>SDS Max</th></tr><tr><td>Shank diameter</td><td>10 mm</td><td>18 mm</td></tr><tr><td>Typical hole range</td><td>4-26 mm</td><td>12-52 mm</td></tr><tr><td>Hammer class</td><td>2-3 kg tools</td><td>5-11 kg tools</td></tr><tr><td>Typical jobs</td><td>Anchors, 1/4-3/4 in holes</td><td>Core drilling, breaking, large anchors</td></tr><tr><td>Common mistake</td><td>Buying Max bits for a Plus tool</td><td>Buying Plus bits and expecting speed</td></tr></table><p><b>Check before you buy:</b> the collar of the chuck, not the drill body. A tool that takes SDS Plus has a spring collar about 25 mm across; the Max collar is visibly larger and heavier.</p><p><b>Also worth knowing:</b> an SDS Plus bit will not fit a keyed chuck without an adapter, and the adapter gives up most of the hammer action.</p>', 'answer_short': 'SDS Plus for rotary hammers up to about 1 in capacity, SDS Max for 1-1/2 in and above. The shanks are different sizes and do not interchange.', 'links': ['HS-8']},
 {'slug': 'bit-extension-for-deep-holes', 'q': 'How do I drill a hole I cannot reach with a normal bit?', 'a': 'Use a quick-change extension with a hex-shank bit for clearance holes, or an aircraft-length bit when the hole has to be accurate. Extensions add runout, so never use them for a precision fit.', 'body': '<table><tr><th>Option</th><th>Reach gained</th><th>Accuracy</th><th>Use for</th></tr><tr><td>Quick-change extension, 150-300 mm</td><td>Yes</td><td>Poor, expect 0.5 mm wander</td><td>Clearance holes, wiring, framing</td></tr><tr><td>Aircraft-length bit</td><td>Up to 300 mm of flute</td><td>Good</td><td>Deep holes in wood and metal</td></tr><tr><td>Chuck extension arbor</td><td>100-200 mm</td><td>Moderate</td><td>Reaching past an obstruction</td></tr><tr><td>Right-angle adapter</td><td>No, changes direction</td><td>Moderate</td><td>Corners, not depth</td></tr></table><p><b>Two things that go wrong:</b> the extension whips at high rpm, and the bit walks because it is further from the chuck. Start the hole with a short bit, then switch to the extension once the point is located.</p>', 'answer_short': 'Quick-change extensions for clearance holes, aircraft-length bits when accuracy matters. Any extension adds runout, so locate the hole with a short bit first.', 'links': ['DB-51C', 'DB-13M']},
 {'slug': 'broken-drill-bit-stuck-in-hole', 'q': 'How do you get a broken drill bit out of a hole?', 'a': 'If it stands proud, grip it and turn it back out; if it is below the surface, drill around it with a smaller solid-carbide bit or burn it out. Never hammer a punch into a hardened bit.', 'body': '<table><tr><th>Situation</th><th>Method</th><th>Risk</th></tr><tr><td>Bit proud of the hole</td><td>Vise-Grips on the shank, turn counter-clockwise while pulling</td><td>Snapping it deeper</td></tr><tr><td>Flush with the surface</td><td>Small solid-carbide bit, drill a ring around it, pick it out</td><td>Carbide shatters if you lever it</td></tr><tr><td>Deep in mild steel</td><td>Take it to a shop with a spark eroder or EDM</td><td>Cost versus a new part</td></tr><tr><td>In aluminium</td><td>Alum solution dissolves the HSS bit, not the workpiece</td><td>Takes 1-3 days</td></tr><tr><td>In wood</td><td>Split the waste out with a chisel, glue a plug back</td><td>Cosmetic only</td></tr></table><p><b>Why bits snap in the first place:</b> side load at the end of the hole, a bit that rubbed instead of cut, or a hand drill at an angle. The exit moment is when most bits break — ease the pressure as the point breaks through.</p>', 'answer_short': 'Grip and turn a proud bit back out; for a bit below the surface, drill a ring around it with a solid-carbide bit or have it spark-eroded. Never punch a hardened bit.', 'links': ['DB-51C', 'DB-13M']},
 {'slug': 'remove-broken-tap-with-alum', 'q': 'Can alum dissolve a broken tap?', 'a': 'Yes in aluminium workpieces only: a saturated alum solution held at about 50 C eats an HSS tap over one to three days and leaves the aluminium alone.', 'body': '<table><tr><th>Workpiece</th><th>Alum works?</th><th>Alternative</th></tr><tr><td>Aluminium</td><td>Yes, the standard trick</td><td>Also: tap extractor with flutes</td></tr><tr><td>Brass or copper</td><td>Partially</td><td>Careful heat and a punch</td></tr><tr><td>Steel</td><td>No</td><td>Spark eroder, or drill out and fit an insert</td></tr><tr><td>Cast iron</td><td>No</td><td>Drill out, thread insert</td></tr></table><p><b>Process:</b> dissolve alum powder in hot water until no more will dissolve, suspend the part in it, keep it warm, and top up the water. Check daily — the tap turns to a black sludge you can flush out.</p><p><b>Prevention is cheaper:</b> a broken tap usually means the tap was turned without backing out the chip, or the hole was drilled undersize. Two turns in, half turn back, with cutting fluid.</p>', 'answer_short': 'In aluminium, yes — a warm saturated alum solution dissolves the tap in one to three days. In steel it does nothing, so use spark erosion or an insert instead.', 'links': ['TD-40', 'TD-40B']},
 {'slug': 'best-cutting-fluid-for-tapping', 'q': 'What is the best lubricant for tapping?', 'a': 'Sulphurised tapping fluid for steel, kerosene or light oil for aluminium, and nothing at all for cast iron. The wrong fluid is worse than none in aluminium.', 'body': '<table><tr><th>Material</th><th>Fluid</th><th>Note</th></tr><tr><td>Mild steel</td><td>Sulphurised or chlorinated tapping fluid</td><td>Paste is better than thin oil on vertical holes</td></tr><tr><td>Stainless</td><td>Heavy tapping paste, generous</td><td>Never tap stainless dry</td></tr><tr><td>Aluminium</td><td>Kerosene, WD-40, or light oil</td><td>Thin fluids stop the chip welding</td></tr><tr><td>Brass</td><td>Light oil, or dry</td><td>Dry is acceptable</td></tr><tr><td>Cast iron</td><td>Dry</td><td>Fluid makes graphite paste that clogs flutes</td></tr></table><p><b>How much:</b> a drop on the tap and a drop in the hole per half turn on deep holes. Flooding a blind hole does nothing except push chips back down.</p><p><b>Technique outranks fluid:</b> start square, two turns forward, half turn back to break the chip, and clear the flutes on every third pass.</p>', 'answer_short': 'Sulphurised tapping fluid for steel, kerosene or light oil for aluminium, dry for cast iron. In aluminium the wrong lubricant makes the chip weld to the flutes.', 'links': ['TD-40', 'TD-40T']},
 {'slug': 'cutting-oil-vs-wd40-for-drilling', 'q': 'Is WD-40 good enough as cutting fluid?', 'a': 'For aluminium and light drilling, yes. For steel it evaporates before it does any work, and holes burn and work-harden.', 'body': '<table><tr><th>Fluid</th><th>Aluminium</th><th>Mild steel</th><th>Stainless</th></tr><tr><td>WD-40</td><td>Good</td><td>Poor</td><td>Poor</td></tr><tr><td>Motor oil</td><td>Acceptable</td><td>Acceptable, slow</td><td>Poor</td></tr><tr><td>Tapping fluid / paste</td><td>Too heavy</td><td>Good</td><td>Good</td></tr><tr><td>Water-soluble coolant</td><td>Good</td><td>Good</td><td>Good, flood it</td></tr></table><p><b>What the fluid is actually doing:</b> cooling the edge and preventing the chip from welding to the flute. Extremely thin oils fail at the second job and do nothing at the first when the hole gets hot.</p><p><b>Cheap upgrade:</b> a stick of tapping wax on the bit costs less than a ruined hole and works on steel, stainless and aluminium.</p>', 'answer_short': 'WD-40 works on aluminium and light drilling. On steel it evaporates too fast to protect the edge, so holes burn and work-harden.', 'links': ['DB-13M', 'TD-40B']},
 {'slug': 'router-bit-for-oak-and-hickory', 'q': 'What router bit do I need for oak and hickory?', 'a': 'Carbide, 1/2 in shank for anything deeper than 6 mm, and lighter passes. Hickory is hard enough to chip a 1/4 in shank on a deep cut.', 'body': '<table><tr><th>Wood</th><th>Janka (lbf)</th><th>Shank</th><th>Depth per pass</th></tr><tr><td>Red oak</td><td>1,290</td><td>1/4 in ok to 6 mm, 1/2 in above</td><td>3-6 mm</td></tr><tr><td>White oak</td><td>1,360</td><td>1/2 in</td><td>3-5 mm</td></tr><tr><td>Hard maple</td><td>1,450</td><td>1/2 in</td><td>3 mm</td></tr><tr><td>Hickory</td><td>1,820</td><td>1/2 in only</td><td>2-3 mm</td></tr></table><p><b>Speed:</b> 16,000-18,000 rpm for a 1/2 in bit in these woods. Run faster and the edge scorches; run slower and the bit hammers instead of slicing.</p><p><b>Order of cuts that works:</b> climb cut 0.5 mm to establish the edge, then conventional passes at 3 mm each, then one full-depth finishing pass with a bearing guided bit.</p>', 'answer_short': 'Carbide, 1/2 in shank above 6 mm depth, and 2-3 mm passes in hickory. These woods chip a 1/4 in shank on deep cuts.', 'links': ['RB-12HW', 'RB-15HW']},
 {'slug': 'router-bit-for-pine-and-softwood', 'q': 'Why does pine burn and fuzz when I route it?', 'a': 'Pine burns from feeding too slowly, not from rpm being too high. Keep the bit moving at a steady rate and take one full-depth pass where the cutter allows it.', 'body': '<table><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr><tr><td>Brown scorch line on the profile</td><td>Bit stopped or slowed in the cut</td><td>Constant feed, do not dwell at corners</td></tr><tr><td>Fuzzy surface</td><td>Dull bit, or cutting against the grain</td><td>New bit, check grain direction</td></tr><tr><td>Torn end grain</td><td>Exit without backing</td><td>Backer board, or climb cut the last 10 mm</td></tr><tr><td>Resin on the bit every pass</td><td>Heat from a dull edge</td><td>Clean and replace; pine punishes a dull bit fast</td></tr></table><p><b>The softwood trap:</b> it cuts so easily that people slow down and take light passes. That is exactly what burns it. Firm, continuous feed beats any rpm change.</p>', 'answer_short': 'Pine burns because the bit dwells in the cut, not because rpm is too high. Keep a firm, continuous feed and stop at corners as little as possible.', 'links': ['RB-12W', 'RB-12P']},
 {'slug': 'cutting-ipe-and-exotic-decking', 'q': 'How do you drill and cut ipe decking?', 'a': 'Carbide only, pilot every screw hole, and count on replacing cutters sooner. Ipe is dense and abrasive enough that a plain HSS bit will not survive one deck.', 'body': '<table><tr><th>Task</th><th>Tool</th><th>Note</th></tr><tr><td>Screw pilot holes</td><td>Carbide-tipped or cobalt bit, 0.5 mm under screw shank</td><td>Ipe splits without a pilot, always</td></tr><tr><td>Cross cuts</td><td>Carbide toothed blade, 40-60 teeth</td><td>Wax the blade, slow the feed</td></tr><tr><td>Ripping</td><td>Thin kerf carbide</td><td>Expect burning, keep moving</td></tr><tr><td>Holes for bolts</td><td>Brad-point or auger, carbide preferred</td><td>Clear chips every inch</td></tr><tr><td>Countersinking</td><td>Carbide countersink</td><td>HSS dulls in under 20 holes</td></tr></table><p><b>Two habits:</b> wax the bit or blade before each run, and let the tool cut rather than forcing it — ipe generates heat fast and heat kills the edge.</p>', 'answer_short': 'Carbide cutters, a pilot hole for every screw, and wax on the blade. Ipe is dense and abrasive enough to destroy plain HSS bits in one deck.', 'links': ['DB-21M', 'DB-51C']},
 {'slug': 'tin-vs-black-oxide-drill-bits', 'q': 'TiN coated or black oxide drill bits?', 'a': 'Black oxide for general shop work, TiN only for repetitive drilling in steel. Once you sharpen either, the coating is gone and you are back to the base HSS.', 'body': '<table><tr><th></th><th>Black oxide</th><th>TiN</th><th>Bare HSS</th></tr><tr><td>Surface hardness</td><td>Slight gain</td><td>Higher</td><td>Base</td></tr><tr><td>Holds oil</td><td>Yes, good for hand drilling</td><td>Less</td><td>No</td></tr><tr><td>Survives resharpening</td><td>Partly</td><td>No</td><td>N/A</td></tr><tr><td>Real benefit</td><td>Corrosion resistance, chip flow</td><td>Life in production steel drilling</td><td>Cheapest</td></tr></table><p><b>What actually decides bit life:</b> cobalt content and point geometry, not the colour. An M35 cobalt bit with a 135 degree split point outlasts any coated plain HSS bit in steel.</p><p><b>Buying rule:</b> wood and general repair, black oxide or bare HSS. Steel and stainless, cobalt. Repetitive drilling in a fixture, coated cobalt.</p>', 'answer_short': 'Black oxide for general work, TiN for repetitive steel drilling. The coating disappears at the first sharpening, so cobalt content matters more than colour.', 'links': ['DB-51C', 'DB-13M']},
 {'slug': 'altin-vs-tialn-coating', 'q': 'AlTiN or TiAlN coating — does it matter?', 'a': 'They are the same coating written two ways. What matters is whether the tool runs hot and dry, which is what AlTiN is for, versus wet and cool, where TiN or uncoated is fine.', 'body': '<table><tr><th>Coating</th><th>Runs best</th><th>Use for</th><th>Avoid in</th></tr><tr><td>TiN (gold)</td><td>Wet, moderate speed</td><td>General steel, taps</td><td>Aluminium, cast iron</td></tr><tr><td>TiCN</td><td>Wet or dry, harder</td><td>Stainless, harder steels</td><td>Deep pockets in aluminium</td></tr><tr><td>AlTiN / TiAlN</td><td>Hot and dry</td><td>Hardened steel, high speed milling</td><td>Aluminium — the aluminium sticks</td></tr><tr><td>DLC</td><td>Dry</td><td>Aluminium, composites, plastics</td><td>Steel</td></tr></table><p><b>Why people get confused:</b> the two spellings describe the same aluminium-titanium-nitride layer; some tool listings put the aluminium first. Both need heat to form their oxide layer, so running them slow and wet wastes the coating.</p><p><b>Rule:</b> aluminium and composites get DLC or uncoated polished. Hardened steel gets AlTiN, run hard. Everything else, cobalt HSS is enough.</p>', 'answer_short': 'AlTiN and TiAlN are the same coating. It needs heat to work, so run it hard and dry in steel; in aluminium it fails because the chip welds to it.', 'links': ['CB-10D', 'DB-51C']},
 {'slug': 'diamond-coated-router-bits', 'q': 'Are diamond-coated router bits worth it?', 'a': 'Only for carbon fiber, fiberglass and other abrasive composites. On wood the coating adds nothing, and a coated bit cannot be resharpened.', 'body': '<table><tr><th>Material</th><th>Diamond coating</th><th>Better choice</th></tr><tr><td>Carbon fiber</td><td>Yes, big life gain</td><td>Also: compression geometry for fraying</td></tr><tr><td>Fiberglass</td><td>Yes</td><td>Diamond or solid carbide, dust extraction is mandatory</td></tr><tr><td>MDF and particleboard</td><td>Some gain</td><td>Standard carbide is enough</td></tr><tr><td>Hardwood</td><td>No benefit</td><td>Standard carbide</td></tr><tr><td>Aluminium</td><td>No</td><td>Single-flute carbide, wax</td></tr></table><p><b>The catch:</b> a diamond film is microns thick, so sharpening removes it. You are buying a disposable edge with a long life, not a repairable one.</p><p><b>Safety note on composites:</b> the dust is the real hazard. Cut wet or with extraction at the cutter, and wear a respirator rated for fine particulate.</p>', 'answer_short': 'Only for carbon fiber and fiberglass, where they last far longer. On wood they add nothing, and a diamond-coated edge cannot be resharpened.', 'links': ['RB-12Z8', 'CB-10D']},
 {'slug': 'jacobs-taper-vs-morse-taper', 'q': 'Jacobs taper or Morse taper for a drill chuck?', 'a': 'Morse taper (MT2, MT3) mates the arbor to the machine spindle. Jacobs taper (JT33, JT6) mates the chuck to the arbor. You need both numbers to order a chuck that fits.', 'body': '<table><tr><th>Taper</th><th>Where it is</th><th>Typical sizes</th></tr><tr><td>Morse taper</td><td>Machine spindle to arbor</td><td>MT1, MT2, MT3</td></tr><tr><td>Jacobs taper</td><td>Arbor to chuck body</td><td>JT0, JT6, JT33, JT3</td></tr><tr><td>R8</td><td>Mill spindle to collet or chuck</td><td>R8 arbor</td></tr></table><p><b>How to order correctly:</b> read the stamp on the existing arbor, for example "MT2 / JT33". That single line is the whole spec. Guessing from the drill size does not work.</p><p><b>Why tapers slip:</b> oil or dirt on the taper, or a burr from a previous spin. Clean both faces with solvent, seat firmly, and never grease a Morse taper — it is held by friction, not by lubricant.</p>', 'answer_short': 'Morse taper fits the machine spindle, Jacobs taper fits the chuck body. Read both numbers off the old arbor before ordering a replacement.', 'links': ['DB-51C', 'DB-21M']},
 {'slug': 'er-collet-vs-r8', 'q': 'ER collet or R8 for a benchtop mill?', 'a': 'R8 is the spindle interface on many mills; ER20 or ER25 hold the cutter. If your mill is R8, you run an R8-to-ER adapter, so the answer is both, not either.', 'body': '<table><tr><th></th><th>R8 collet</th><th>ER collet</th></tr><tr><td>What it holds</td><td>One tool per collet, direct in the spindle</td><td>Any shank within its range, via nut</td></tr><tr><td>Range</td><td>Fixed size per collet</td><td>ER20: 1-13 mm, ER25: 1-16 mm</td></tr><tr><td>Grip length</td><td>Short</td><td>Longer, better for side load</td></tr><tr><td>Change speed</td><td>Slow, drawbar</td><td>Fast, one nut</td></tr><tr><td>Runout</td><td>Good</td><td>Good if the nut is clean and torqued</td></tr></table><p><b>Practical setup:</b> R8-to-ER20 adapter in the spindle, then one ER20 nut for every cutter. That covers 1-13 mm with five collets instead of a full R8 set.</p><p><b>Torque matters:</b> an ER nut that is hand-tight will let the cutter creep. Use the specified torque, usually around 40-70 Nm for ER20.</p>', 'answer_short': 'R8 is the spindle interface, ER is the workholding. On an R8 mill you use an R8-to-ER adapter, so you need both.', 'links': ['RB-12Z8', 'RB-12Z']},
 {'slug': 'router-kickback-causes', 'q': 'What causes router kickback and how do I stop it?', 'a': 'Feeding in the direction of cutter rotation, taking too deep a cut, or letting the bit grab a corner. Every edge cut should feed against the rotation.', 'body': '<table><tr><th>Cause</th><th>What happens</th><th>Fix</th></tr><tr><td>Climb feeding a large cutter</td><td>Bit grabs and pulls the work</td><td>Feed against rotation; climb only 0.5 mm</td></tr><tr><td>Too deep a pass</td><td>Bit bogs, then snatches</td><td>3 mm maximum per pass in hardwood</td></tr><tr><td>Routing a narrow offcut</td><td>No control, work launches</td><td>Push sticks, featherboards, wider stock</td></tr><tr><td>Bit loose in the collet</td><td>Bit creeps down, sudden grab</td><td>Clean collet, correct torque</td></tr><tr><td>Grain reversal at a corner</td><td>Edge digs in</td><td>Slow down at the corner, or rout before cutting to size</td></tr></table><p><b>Hand-held rule:</b> the router moves left to right along the outside of a piece so the cutter pulls the body of the tool away from you. On a table, feed right to left against the rotation.</p>', 'answer_short': 'Kickback comes from feeding with the cutter rotation, too deep a pass, or a bit grabbing a corner. Feed against rotation and keep passes to 3 mm.', 'links': ['RB-15W', 'RB-12W']},
 {'slug': 'router-table-safety-checklist', 'q': 'What should I check before using a router table?', 'a': 'Fence locked, bit tight, guard and featherboards in place, workpiece clear of the bit at start-up, and push sticks within reach. Thirty seconds of checks prevents most table injuries.', 'body': '<table><tr><th>Check</th><th>Pass condition</th><th>Fail consequence</th></tr><tr><td>Bit in collet</td><td>Seated fully, nut torqued</td><td>Bit creeps out at speed</td></tr><tr><td>Fence</td><td>Both locks tight, square to table</td><td>Work kicks sideways</td></tr><tr><td>Guard / splitter</td><td>Fitted and adjusted to stock thickness</td><td>Hands exposed at the cutter</td></tr><tr><td>Featherboard</td><td>Holds stock down and against fence</td><td>Climb cut by accident</td></tr><tr><td>Start-up clearance</td><td>Stock not touching the bit</td><td>Snatch on power-up</td></tr><tr><td>Push sticks</td><td>Two within reach</td><td>Hands near a 20,000 rpm cutter</td></tr></table><p><b>Also check the obvious:</b> the router is clamped in the table, the power lead is behind you, and eye and hearing protection are on. Table routing is louder than hand routing and the cutter is at chest height.</p>', 'answer_short': 'Check bit seating, fence locks, guard, featherboards and start-up clearance, with two push sticks in reach. Most table router injuries come from a check skipped, not a tool failure.', 'links': ['RB-12HW', 'RB-15HW']},
 {'slug': 'dust-collection-for-router-table', 'q': 'Do I need dust collection on a router table?', 'a': 'Yes for MDF, particleboard and any production work. The dust is a health hazard and it also packs the cut, which overheats the bit and burns the edge.', 'body': '<table><tr><th>Setup</th><th>Airflow</th><th>Result</th></tr><tr><td>Nothing</td><td>0</td><td>Visible cloud, chips in the cut</td></tr><tr><td>Shop vac at the fence port</td><td>About 100 CFM</td><td>Most of the chip load, fine dust remains</td></tr><tr><td>Shop vac at fence plus box under the table</td><td>150-200 CFM</td><td>Good for MDF in a small shop</td></tr><tr><td>Dust extractor, 2 in hose</td><td>300+ CFM</td><td>Production level, best for fine dust</td></tr></table><p><b>Why the fence port alone is not enough:</b> the cutter throws most of the dust downward. A box around the bit under the table catches it before it settles in the shop.</p><p><b>Respirator:</b> a shop vac does not remove the finest fraction. If you cut MDF regularly, wear a P2/P100 respirator as well.</p>', 'answer_short': 'Yes for MDF and production work. A shop vac at the fence port handles chips, and a box under the table catches the dust the cutter throws downward.', 'links': ['RB-12W', 'RB-15W']},
 {'slug': 'router-bit-set-price-tiers', 'q': 'What am I actually paying for in a more expensive router bit set?', 'a': 'Carbide grade, bearing quality and shank tolerance — not piece count. Two 12-piece sets can differ by five times in price and look identical in the box.', 'body': '<table><tr><th>Part</th><th>Low end</th><th>High end</th><th>How to check</th></tr><tr><td>Carbide</td><td>Thin tips, grade not stated</td><td>Micro-grain, grade stated</td><td>Look for a hardness or grade callout</td></tr><tr><td>Bearing</td><td>Open, rough spin</td><td>Sealed, spins free</td><td>Spin it in the shop before buying</td></tr><tr><td>Shank</td><td>Loose tolerance</td><td>Ground to 0.01 mm</td><td>Measure with a caliper</td></tr><tr><td>Balance</td><td>Vibrates above 20k rpm</td><td>Runs smooth at full speed</td><td>Listen to a test cut</td></tr><tr><td>Profiles</td><td>Duplicated across shank sizes</td><td>Distinct profiles</td><td>Count profiles, not pieces</td></tr></table><p><b>The honest split:</b> for occasional softwood work, a mid-range set is the right answer. For daily hardwood or MDF, the bearing and the carbide grade are where the money has to go.</p><p><b>Buying check:</b> a listing that names the carbide grade and the bearing spec is usually a serious set. One that lists only piece count and rpm is not.</p>', 'answer_short': 'Carbide grade, bearing quality and shank tolerance decide the price. A set that lists only piece count tells you nothing about how long it will cut.', 'links': ['RB-12W', 'RB-15HW']},
 {'slug': 'single-router-bit-vs-set', 'q': 'Should I buy one good bit or a whole set?', 'a': 'One good bit if you know the exact profile you need. A set if you are still building furniture and need options — but below three profiles, single bits are cheaper.', 'body': '<table><tr><th>Your situation</th><th>Buy</th><th>Why</th></tr><tr><td>One job, one profile</td><td>Single bit</td><td>You will not use the rest</td></tr><tr><td>Learning, no plan yet</td><td>12-piece set</td><td>Cheapest way to try profiles</td></tr><tr><td>Replacing a worn bit</td><td>Single bit, better grade</td><td>Upgrade where it matters</td></tr><tr><td>Door and window work</td><td>Single bits, 1/2 in shank</td><td>Deep cuts need the bigger shank</td></tr><tr><td>Production run</td><td>Match the set to the job</td><td>Duplicate the one profile you wear out</td></tr></table><p><b>The trap in cheap single bits:</b> a $12 single bit with an unspecifed carbide is worse than the equivalent bit in a mid-range set. Price per profile is not the same as edge quality.</p>', 'answer_short': 'Buy one bit when you know the profile, a set when you are still exploring. Price per profile only wins if the single bit is the same carbide grade as the set.', 'links': ['RB-12W', 'RB-12P']},
 {'slug': 'tap-and-die-set-metric-or-sae', 'q': 'Which tap and die set should I start with — metric or SAE?', 'a': 'Buy the one that matches the fasteners you actually handle. SAE for US machinery, plumbing fittings and older equipment; metric for anything imported after the 1990s.', 'body': '<table><tr><th>What you work on</th><th>Set</th><th>Typical sizes</th></tr><tr><td>US-built machinery, vintage tools</td><td>SAE (NC/NF)</td><td>1/4-20, 5/16-18, 3/8-16</td></tr><tr><td>Imported power tools, bikes, ATVs</td><td>Metric</td><td>M6, M8, M10, M12</td></tr><tr><td>Automotive general</td><td>Both</td><td>M6-M12 plus 1/4-3/8</td></tr><tr><td>Plumbing and pipe</td><td>Neither — NPT</td><td>1/8, 1/4, 3/8 NPT</td></tr></table><p><b>What a set should contain:</b> taper, plug and bottoming taps in the common sizes, matching dies, a tap wrench, a die stock, and a thread pitch gauge. A set without a gauge cannot tell you which tap to use.</p><p><b>The buying mistake:</b> a 40-piece set that is 40 sizes of one tap style. Count tap styles, not pieces.</p>', 'answer_short': 'Buy metric if your fasteners are imported, SAE if they are US-built. NPT pipe threads come from neither set and need their own taps.', 'links': ['TD-40', 'TD-40T']},
 {'slug': 'door-lock-hole-sizes', 'q': 'What size hole saw do I need for a door knob?', 'a': '2-1/8 in (54 mm) for the knob bore through the face, and 1 in (25 mm) for the latch bore from the door edge. Drill the latch hole first.', 'body': '<table><tr><th>Hole</th><th>Size</th><th>Where</th><th>Note</th></tr><tr><td>Knob / deadbolt bore</td><td>2-1/8 in (54 mm)</td><td>Through the door face</td><td>Standard for US residential</td></tr><tr><td>Latch bore</td><td>1 in (25 mm)</td><td>Door edge, centred in the 2-1/8 in bore</td><td>Drill this first from both sides</td></tr><tr><td>Deadbolt bore</td><td>2-1/8 in</td><td>6-12 in above the knob</td><td>Same saw as the knob</td></tr><tr><td>Strike plate</td><td>Chisel, 1 in x 2-1/4 in</td><td>Jamb</td><td>No saw</td></tr></table><p><b>Order of operations:</b> mark both faces with the template, drill the 1 in latch hole from the edge until the point breaks through the face, then use the 2-1/8 in saw from both faces to avoid blowout on the veneer.</p><p><b>Backer matters:</b> hollow-core doors need a light touch and a sharp saw; the cardboard inside collapses if you push.</p>', 'answer_short': 'A 2-1/8 in hole saw for the knob bore and 1 in for the latch. Drill the latch hole from the edge first, then bore the face from both sides.', 'links': ['HS-8']},
 {'slug': 'auger-bit-for-wiring-studs', 'q': 'What size auger bit should I use for running wire through studs?', 'a': '3/4 in for one or two cables, 1 in if you may pull more later. Keep the hole at least 1-1/4 in from the stud face, or cover it with a nail plate.', 'body': '<table><tr><th>Cable run</th><th>Hole</th><th>Note</th></tr><tr><td>One 14/2 or 12/2</td><td>5/8-3/4 in</td><td>Leaves room to pull</td></tr><tr><td>Two cables</td><td>3/4 in</td><td>Most common choice</td></tr><tr><td>Three or more</td><td>1 in</td><td>Do not exceed 40% of stud depth</td></tr><tr><td>Conduit through plate</td><td>Match the conduit OD</td><td>Bush the edge</td></tr></table><p><b>The rule that gets inspected:</b> holes must be at least 1-1/4 in from the nearest stud edge. Closer than that and the cable needs a steel nail plate. Check your local code before drilling a whole wall.</p><p><b>Tool:</b> an auger bit with a screw point, in a right-angle drill for tight stud bays. Clear the flutes every few inches — packed chips are what stalls the drill.</p>', 'answer_short': 'Three-quarter inch for one or two cables, 1 in if you may add more. Keep holes 1-1/4 in from the stud face or fit a nail plate.', 'links': ['DB-21M', 'DB-51C']},
 {'slug': 'hole-saw-size-for-pvc-pipe', 'q': 'What size hole saw for 1-1/2 in PVC pipe?', 'a': 'Measure the outside diameter, not the nominal size: 1-1/2 in PVC is 1.900 in OD, so a 2 in hole saw gives a working clearance fit.', 'body': '<table><tr><th>Nominal</th><th>Actual OD</th><th>Hole saw</th></tr><tr><td>1/2 in</td><td>0.840 in</td><td>7/8 in</td></tr><tr><td>3/4 in</td><td>1.050 in</td><td>1-1/8 in</td></tr><tr><td>1 in</td><td>1.315 in</td><td>1-3/8 in</td></tr><tr><td>1-1/2 in</td><td>1.900 in</td><td>2 in</td></tr><tr><td>2 in</td><td>2.375 in</td><td>2-1/2 in</td></tr></table><p><b>Why the saw is bigger than the pipe:</b> pipe has to slide through the hole, and PVC expands slightly with temperature. A hole exactly at OD will not take the fitting.</p><p><b>Cutting PVC cleanly:</b> slow rpm, light pressure, and back the workpiece with scrap. PVC grabs and cracks if the saw is fed hard, and it chips when the teeth exit.</p>', 'answer_short': 'For 1-1/2 in PVC, use a 2 in hole saw — the pipe is 1.900 in outside diameter, so nominal size and saw size never match.', 'links': ['HS-8']},
 {'slug': 'drilling-fence-post-holes', 'q': 'How do I drill holes for fence posts?', 'a': 'A power auger with a bit 2 in wider than the post for concrete, or 1 in wider for gravel. Call 811 before the first hole, every time.', 'body': '<table><tr><th>Post</th><th>Hole diameter</th><th>Depth</th></tr><tr><td>4x4 in concrete</td><td>10-12 in</td><td>Frost line plus 6 in</td></tr><tr><td>4x4 in gravel</td><td>8-9 in</td><td>24-30 in</td></tr><tr><td>6x6 in concrete</td><td>12-14 in</td><td>Frost line plus 6 in</td></tr><tr><td>Rail or picket pilot holes</td><td>Bit 1 mm under the screw shank</td><td>Through the rail</td></tr></table><p><b>Sequence:</b> mark the line, call 811, dig with a post hole digger or auger, check plumb with a level on two faces, then set with concrete or compacted gravel. Do not drill through a utility locate mark, and re-check depth before pouring.</p><p><b>Tool notes:</b> one-man augers need a firm stance and low speed; in rocky soil a digging bar saves the gearbox. For rail pilot holes, a cobalt or brad-point bit stops splitting.</p>', 'answer_short': 'Use a power auger with a bit 2 in wider than the post and call 811 before digging. Pilot every rail hole 1 mm under the screw shank to stop splitting.', 'links': ['DB-21M', 'DB-13M']},
 {'slug': '35mm-hinge-cup-bit', 'q': 'Do I need a 35 mm bit for concealed hinges?', 'a': 'Yes. Standard European concealed hinges take a 35 mm cup bore, 11-13 mm deep, set 3-5 mm in from the door edge.', 'body': '<table><tr><th>Hinge cup</th><th>Bore</th><th>Depth</th><th>Edge setback</th></tr><tr><td>Standard 35 mm cup</td><td>35 mm</td><td>11-13 mm</td><td>3-5 mm</td></tr><tr><td>26 mm mini cup</td><td>26 mm</td><td>9-11 mm</td><td>3-4 mm</td></tr><tr><td>40 mm cup (heavy doors)</td><td>40 mm</td><td>12-14 mm</td><td>5 mm</td></tr><tr><td>Screw holes on the cup</td><td>2 x 8 mm or 10 mm</td><td>10 mm</td><td>Per template</td></tr></table><p><b>Use a Forstner, not a hole saw:</b> the cup needs a flat bottom and a clean rim, and a Forstner with a brad point or centre spur locates far more accurately. Set a depth stop.</p><p><b>Common scrap:</b> boring from the wrong face, or 1 mm too deep so the cup protrudes. Test on a scrap of the same board thickness first — an 18 mm door and a 20 mm door need different setbacks for the same overlay.</p>', 'answer_short': 'Yes — a 35 mm cup bore, 11-13 mm deep, 3-5 mm from the door edge. Use a Forstner with a depth stop, not a hole saw.', 'links': ['HS-8']},
 {'slug': 'dovetail-bit-angle-8-vs-14', 'q': '8 degree or 14 degree dovetail bit?', 'a': '8 degrees for drawer sides, fine furniture and hardwood. 14 degrees for half-blind joints, softwood and jigs that need a stronger wedge. The bit must match the jig template angle.', 'body': '<table><tr><th>Angle</th><th>Joint strength</th><th>Best for</th><th>Note</th></tr><tr><td>8 degrees</td><td>Good, fine look</td><td>Through dovetails, drawers</td><td>Standard for most jigs</td></tr><tr><td>14 degrees</td><td>Stronger wedge</td><td>Half-blind, softwood</td><td>More forgiving of gaps</td></tr><tr><td>7 degrees</td><td>Specific to some jigs</td><td>Match the template</td><td>Not interchangeable</td></tr></table><p><b>The rule:</b> the bit angle must match the template comb. A 14 degree bit in an 8 degree template cuts a joint that is loose at the tails and tight at the pins.</p><p><b>Setup:</b> set the bit height on scrap of the exact drawer stock thickness, cut one test joint, and check that the tail slides in with hand pressure only. Any hammering means the depth is wrong.</p>', 'answer_short': 'Eight degrees for through dovetails and drawers, 14 for half-blind joints and softwood. The bit angle must match the jig template, and they do not interchange.', 'links': ['RB-15W', 'RB-12W']},
 {'slug': 'router-bit-depth-setting', 'q': 'How do I set router bit depth accurately?', 'a': 'Set it on scrap, cut, measure the result with a caliper, and adjust in 0.1 mm steps. Never set depth by eye on the finished workpiece.', 'body': '<table><tr><th>Step</th><th>Action</th><th>Check</th></tr><tr><td>1</td><td>Zero the bit to the table or base</td><td>Bit just touches, no load</td></tr><tr><td>2</td><td>Set the planned depth on the scale</td><td>Note the number</td></tr><tr><td>3</td><td>Cut a test in scrap of the same thickness</td><td>One full pass, steady feed</td></tr><tr><td>4</td><td>Measure the cut with a caliper</td><td>Compare to the plan</td></tr><tr><td>5</td><td>Adjust by the difference, re-cut</td><td>Within 0.2 mm</td></tr></table><p><b>Why the scale lies:</b> most plunge routers have a scale on the body, not on the cutter. The reference is the base plate, and any base insert or sub-base changes it. Always trust the measured cut, not the printed number.</p><p><b>For repeat work:</b> cut a test piece, leave it on the bench as a gauge, and set the next job against it rather than against the scale.</p>', 'answer_short': 'Set on scrap, cut, measure with a caliper and adjust in 0.1 mm steps. Router scales read from the base plate, so the measured cut is the only number that counts.', 'links': ['RB-12W', 'RB-15HW']},
 {'slug': 'climb-cut-vs-conventional-routing', 'q': 'Should I climb cut with a router?', 'a': 'Only as a light finishing pass of 0.5 mm or less, and only with the work held against a fence or in a jig. Never climb cut hand-held with a large cutter.', 'body': '<table><tr><th>Cut</th><th>Feed direction</th><th>Result</th><th>Safety</th></tr><tr><td>Conventional</td><td>Against cutter rotation</td><td>Clean enough, slight tear-out at exit</td><td>Controlled</td></tr><tr><td>Climb, 0.5 mm</td><td>With rotation</td><td>Cleanest edge on figured wood</td><td>Bit pulls the work — needs a fence</td></tr><tr><td>Climb, full depth</td><td>With rotation</td><td>Ripped workpiece</td><td>Do not</td></tr></table><p><b>Where climb cutting earns its place:</b> tear-out prone species, veneered plywood, and the last 10 mm of an edge where the grain reverses. Take the bulk conventionally, then climb the last pass.</p><p><b>Hand-held exception:</b> none worth the risk at full depth. A trim router with a 3 mm round-over is the only case where a light climb pass is common practice.</p>', 'answer_short': 'Climb cut only as a 0.5 mm finishing pass with the work against a fence. Full-depth climb cuts pull the workpiece out of your hands.', 'links': ['RB-12Z', 'RB-12Z8']},
 {'slug': 'multiple-light-passes-vs-one-deep-cut', 'q': 'Is one deep pass or several light passes faster?', 'a': 'Several light passes are faster overall in hardwood: three passes at 3 mm beat one at 9 mm because the bit stays sharp, the motor does not bog, and you skip the cleanup of a burnt edge.', 'body': '<table><tr><th>Approach</th><th>Time per metre, oak</th><th>Edge quality</th><th>Bit life</th></tr><tr><td>One 9 mm pass</td><td>Fast, then 10 min of sanding</td><td>Burn marks, tear-out</td><td>Short — heat</td></tr><tr><td>Three 3 mm passes</td><td>Similar total time</td><td>Clean, minimal sanding</td><td>Long</td></tr><tr><td>Six 1.5 mm passes</td><td>Slower</td><td>Very clean</td><td>Longest</td></tr></table><p><b>Where one deep pass is right:</b> softwood with a 1/4 in bit at 6 mm, or a rebate where the bearing controls depth. The limit is the bit diameter: as a rule, depth per pass should not exceed half the cutter diameter.</p><p><b>What actually slows you down:</b> not the extra pass, but the sanding, the burnt edge, and the bit you have to replace. Count the whole job, not just the cut.</p>', 'answer_short': 'Light passes win overall: three at 3 mm cut faster than one at 9 mm once you count sanding and bit life. Keep depth under half the cutter diameter.', 'links': ['RB-15W', 'RB-15HW']},
 {'slug': 'why-wood-burns-when-routing', 'q': 'Why does my router burn the wood?', 'a': 'A dull bit or a feed that is too slow for the rpm. The edge rubs instead of slicing, and the friction scorches the surface in under a second.', 'body': '<table><tr><th>Symptom</th><th>Most likely cause</th><th>Fix</th></tr><tr><td>Uniform brown line along the profile</td><td>Feed too slow, rpm too high</td><td>Increase feed or drop rpm by 2,000</td></tr><tr><td>Burn only at corners</td><td>Dwelling in the cut</td><td>Keep moving, or rout before cutting to length</td></tr><tr><td>Burn with a new bit</td><td>Too many flutes for the wood, or too high rpm</td><td>2 flutes, 16,000-18,000 rpm</td></tr><tr><td>Burn and fuzz together</td><td>Dull edge</td><td>Replace or resharpen</td></tr><tr><td>Burn in a deep groove</td><td>Depth too great, chips cannot clear</td><td>Two passes, clear chips</td></tr></table><p><b>Resin makes it worse:</b> a bit with burnt resin on the flutes runs hotter and burns the next piece sooner. Clean the flutes after every session.</p><p><b>Note on cherry and maple:</b> these scorch visibly at temperatures where oak shows nothing. The burn is a warning, not just a cosmetic problem — the same heat is dulling the carbide.</p>', 'answer_short': 'Burn is friction: either the bit is dull or the feed is too slow for the rpm. Speed up the feed or drop 2,000 rpm, and clean resin off the flutes.', 'links': ['RB-12W', 'RB-15W']},
]
